import {openSQLiteStore} from '../../src/services/storage/sqlite.js';import {createSQLiteBotDatabase} from '../../src/services/storage/sqliteBotDatabase.js';import {db} from '../../src/utils/database/wrapper.js';import {WarningService} from '../../src/services/moderation/warningService.js';
const [file,guild,user,moderator]=process.argv.slice(2),sqlite=await openSQLiteStore({path:file,busyTimeout:5000});db.db=createSQLiteBotDatabase(sqlite);db.initialized=true;db.useFallback=false;for(let i=0;i<25;i++)await WarningService.addWarning({guildId:guild,userId:user,moderatorId:moderator,reason:`warning ${i}`,timestamp:1700000000000});sqlite.close();
